+@page "/chat"
+@rendermode InteractiveServer
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <ChannelSidebar Channels="channels"
+                    ActiveChannelId="activeChannelId"
+                    OnChannelSelected="SelectChannel" />
+
+    <div class="chat-main @(threadOpen ? "thread-visible" : "")">
+        @if (activeChannel is not null)
+        {
+            <MessageArea ChannelName="@activeChannel.Name"
+                         ChannelDescription="@activeChannel.Description"
+                         Messages="messages"
+                         ThreadSummaries="threadSummaries"
+                         OnOpenThread="OpenThread"
+                         OnReact="HandleReaction"
+                         OnSendMessage="SendMessage"
+                         OnLoadMore="LoadMoreMessages" />
+        }
+    </div>
+
+    @if (threadOpen && threadRootMessage is not null)
+    {
+        <ThreadPanel RootMessage="threadRootMessage"
+                     Replies="threadReplies"
+                     OnSendReply="SendThreadReply"
+                     OnClose="CloseThread" />
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private List<Message> threadReplies = [];
+    private Dictionary<int, ThreadSummary> threadSummaries = [];
+    private Channel? activeChannel;
+    private int activeChannelId;
+    private bool threadOpen;
+    private Message? threadRootMessage;
+    private int messageSkip;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        activeChannelId = channelId;
+        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messageSkip = 0;
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messageSkip = messages.Count;
+        await ChatService.MarkChannelReadAsync(channelId);
+        BuildThreadSummaries();
+        CloseThread();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            messageSkip += older.Count;
+            BuildThreadSummaries();
+        }
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
+        messages.Add(sent);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Optimistically add the reaction locally
+        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (msg is not null)
+        {
+            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                existing.Users.Add("You");
+            }
+            else
+            {
+                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+        threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update thread summary
+        if (threadSummaries.ContainsKey(threadRootMessage.Id))
+        {
+            var existing = threadSummaries[threadRootMessage.Id];
+            threadSummaries[threadRootMessage.Id] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = DateTime.Now
+            };
+        }
+        else
+        {
+            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, DateTime.Now);
+        }
+    }
+
+    private void BuildThreadSummaries()
+    {
+        threadSummaries = messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .ToDictionary(
+                g => g.Key,
+                g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt))
+            );
+    }
+}
+

toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #ffffff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: white;
    border-radius: 10px;
    padding: 2px 6px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-visible {
    flex: 0 0 55%;
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #ffffff;
}

.message-area-header .channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Individual Message */
.message {
    padding: 8px 12px;
    border-radius: 4px;
    margin-bottom: 4px;
    position: relative;
}

.message:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 600;
    color: #ffffff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
}

.reaction-badge:hover {
    background: #4f545c;
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message Actions */
.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 4px;
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
}

.action-btn:hover {
    background: #4f545c;
    color: #ffffff;
}

/* Emoji Picker */
.emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px;
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

.emoji-btn:hover {
    background: #4f545c;
}

/* Message Input */
.message-input-area,
.thread-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #202225;
    background: #36393f;
}

.message-input {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.message-input:focus {
    outline: none;
    box-shadow: 0 0 0 1px #00aff4;
}

.send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

.thread-header h3 {
    margin: 0;
    color: #ffffff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #4f545c;
    color: #ffffff;
}

.thread-root-message {
    padding: 12px 16px;
    background: #36393f;
    border-bottom: 1px solid #202225;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b9bbbe;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #40444b;
}

.thread-reply:last-child {
    border-bottom: none;
}

.thread-input-area {
    background: #2f3136;
}

