+    font-size: 0.95rem;
+}
+
+.channel-description {
+    font-size: 0.75rem;
+    color: #72767d;
+    margin-top: 2px;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+.unread-badge {
+    position: absolute;
+    right: 8px;
+    top: 50%;
+    transform: translateY(-50%);
+    background: #ed4245;
+    color: white;
+    border-radius: 10px;
+    padding: 2px 6px;
+    font-size: 0.7rem;
+    font-weight: 700;
+}
+
+/* Main Message Area */
+.chat-main {
+    flex: 1;
+    display: flex;
+    min-width: 0;
+}
+
+.chat-main.thread-visible {
+    flex: 0 0 55%;
+}
+
+.message-area {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    background: #36393f;
+    color: #dcddde;
+}
+
+.message-area-header {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+.message-area-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #ffffff;
+}
+
+.message-area-header .channel-desc {
+    margin: 4px 0 0;
+    font-size: 0.8rem;
+    color: #8e9297;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 8px;
+    color: #8e9297;
+    font-size: 0.85rem;
+}
+
+/* Individual Message */
+.message {
+    padding: 8px 12px;
+    border-radius: 4px;
+    margin-bottom: 4px;
+    position: relative;
+}
+
+.message:hover {
+    background: #32353b;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 4px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #ffffff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-wrap: break-word;
+}
+
+.message-reactions {
+    display: flex;
+    gap: 4px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 12px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    color: #dcddde;
+}
+
+.reaction-badge:hover {
+    background: #4f545c;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #00aff4;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message Actions */
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 4px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 0.75rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #4f545c;
+    color: #ffffff;
+}
+
+/* Emoji Picker */
+.emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    z-index: 10;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #4f545c;
+}
+
+/* Message Input */
+.message-input-area,
+.thread-input-area {
+    display: flex;
+    gap: 8px;
+    padding: 12px 16px;
+    border-top: 1px solid #202225;
+    background: #36393f;
+}
+
+.message-input {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.message-input:focus {
+    outline: none;
+    box-shadow: 0 0 0 1px #00aff4;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: white;
+    border: none;
+    border-radius: 8px;
+    padding: 8px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    color: #ffffff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #4f545c;
+    color: #ffffff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+    font-size: 0.85rem;
+    color: #b9bbbe;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #40444b;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+
+.thread-input-area {
+    background: #2f3136;
+}
+

